package pp.ua.avertooserver.security.captcha;

/**
 * Service responsible for validating CAPTCHA tokens
 * received from client applications.
 *
 * <p>The interface hides the concrete CAPTCHA provider
 * from the rest of the application. This allows us to
 * replace or extend the CAPTCHA provider later without
 * changing registration logic.</p>
 */
public interface CaptchaService {

    /**
     * Validates a CAPTCHA token received from a client.
     *
     * @param token CAPTCHA token generated by the client
     * @return {@code true} if the token is valid
     */
    boolean verify(String token);
}